export const COMPANIES = Object.values(COMPANY_DATA);

export const TIERS = [...new Set(COMPANIES.map(c => c.tier))];

export function getCompanyProblems(companyId, window = "sixMonths") {
  const company = COMPANY_DATA[companyId];
  if (!company) return [];
  return company[window] || company.sixMonths || [];
}
